package com.bank.hiringtrend;

import java.time.LocalDate;
import java.util.*;
import java.util.logging.*;
import static java.util.stream.Collectors.*;

public class PeakYearDemo {
    private static final Logger log = Logger.getLogger("HiringTrend");
    static {
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
    }

    public static void main(String[] args) {
        List<Employee> staff = List.of(
            new Employee("Rajesh", LocalDate.parse("2020-01-15")),
            new Employee("Priya", LocalDate.parse("2020-07-01")),
            new Employee("Amit", LocalDate.parse("2020-09-10")),  // 2020 has 3
            new Employee("Neha", LocalDate.parse("2022-03-10")));
        HiringTrendService service = new HiringTrendService();

        log.info(() -> "Peak hiring year: " + service.peakHiringYear(staff).orElse(-1));
    }
}

// ─── Would be in model/Employee.java ───
class Employee {
    private final String name;
    private final LocalDate joinDate;
    Employee(String name, LocalDate joinDate) { this.name = name; this.joinDate = joinDate; }
    LocalDate getJoinDate() { return joinDate; }
}

// ─── Would be in service/HiringTrendService.java ───
class HiringTrendService {
    Optional<Integer> peakHiringYear(List<Employee> staff) {
        Map<Integer, Long> perYear = staff.stream()
            .filter(e -> e.getJoinDate() != null)
            .collect(groupingBy(e -> e.getJoinDate().getYear(), counting())); // joiners/year
        return perYear.entrySet().stream()
            .max(Map.Entry.<Integer, Long>comparingByValue()
                .thenComparing(Map.Entry.comparingByKey()))                   // tie → earlier year
            .map(Map.Entry::getKey);
    }
}
